fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping from digit character to its "good count"
    let good_count = |c: char| -> u32 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => panic!("Invalid digit"),
        }
    };
    
    // Get the first two characters
    let first_digit = input[0];
    let second_digit = input[1];
    
    // Calculate the product of their good counts
    let product = good_count(first_digit) * good_count(second_digit);
    
    // Convert product to string and then to Vec<char>
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Add trailing newline
    result.push('\n');
    
    result
}